                width_needed = c * (a + c)  # width for c columns with gaps
                height_needed = r * (a + r)  # height for r rows with gaps

                x_h = (h - r * a) / (r + 1) if r > 0 else float('inf')
                x_w = (w - c * a) / (c + 1) if c > 0 else float('inf')

                x = min(x_h, x_w)
                if x >= 0:
                    min_x = min(min_x, x)

    if min_x == float('inf'):
