                if arr[i + 1] < 0:
                    return False
            return True

        possible = False
        for i in range(n - 1):
            arr_original = list(a)
            arr_original[i], arr_original[i + 1] = arr_original[i + 1], arr_original[i]
            # Reset modified values for next iteration
            possible = possible or can_clean(arr_original)
            break
        else:
            possible = can_clean(a)

