        visited = set()
        visited.add((start_x, start_y))

        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        while queue:
            x, y = queue.pop(0)
            component.append((x, y))
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m:
                    if grid[nx][ny] == '.' and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append((nx, ny))
        return component

    component_rows = set()
    component_cols = set()

    visited_rooms = set()
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and (i, j) not in visited_rooms:
                comp = bfs(i, j)
                visited_rooms.update(comp)
                component_rows.update(row for row, col in comp)
                component_cols.update(col for row, col in comp)

    if not component_rows:
        return '\n'.join(''.join(row) for row in grid)

    rows = list(component_rows)
    cols = list(component_cols)

