    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def minimal_roots_f(n):
    if n == 1:
        return 1
    primes = []
    f = {n: factorize(n)}
    parsed = False
    for ai_str in re.split(r'\s+', n):
