    import sys
    sys.setrecursionlimit(2000)

    n, m = map(int, s.split('\n')[0].split())
    patterns = []
    for i in range(1, m + 1):
        patterns.append(s.split('\n')[i])

    MOD = 1000000009

    def solve():
        from collections import deque

        # Build Aho-Corasick automaton
        trie = [{'next': {}, 'fail': 0, 'terminal': False}]

        for p in patterns:
            node = 0
            for c in p:
                if c not in trie[node]['next']:
                    trie[node]['next'][c] = len(trie)
                    trie.append({'next': {}, 'fail': 0, 'terminal': False})
                node = trie[node]['next'][c]
            trie[node]['terminal'] = True

        for node in range(1, len(trie)):
            parent = trie[node]['fail']
            while parent != 0 and trie[parent]['fail'] != 0:
                char = chr(65 + (node - trie[node]['fail'] - 1))
                trie.parent = [trie[node]['fail']]

        for i in range(len(trie)):
            for c in 'ACGT':
                if c in trie[i]['next']:
                    trie[trie[i]['next'][c]]['fail'] = trie[i]['next'][c]
                else:
                    trie[i]['next'][c] = trie[trie[i]['fail']]

        memo = {}

        def dp(pos, mask):
            if pos > n:
                return 1 if mask == (1 << n) - 1 else 0
            if (pos, mask) in memo:
                return memo[(pos, mask)]

            res = 0
            for p_idx, p in enumerate(patterns):
                res += dp(pos + 1, mask | (1 << p)))
            memo[(pos, mask)] = res % MOD
            return res

        print(dp(0, 0))
