class SegmentTree:
    def __init__(self, n):
        self.N = 1
        while self.N < n + 2:
            self.N *= 2
        self.p = [1.0] * (2 * self.N)

    def update(self, i, val):
        i += self.N
        self.p[i] = val
        i //= 2
        while i:
            self.p[i] = self.p[2 * i] * self.p[2 * i + 1]
            i //= 2

    def query(self, l, r):
        l += self.N - 1
        r += self.N - 1
        res = 1.0
        while l <= r:
            if l % 2 == 1:
                res *= self.p[l]
                l += 1
            if r % 2 == 0:
                res *= self.p[r]
                r -= 1
            l //= 2
            r //= 2
        return res


def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, q = map(int, lines[0].split())
    p = []
    for i in range(n):
        a, b = map(int, lines[i + 1].split())
        p.append((a, b))

    st = SegmentTree(n)
    for i in range(n):
        st.update(i + 1, p[i][0] / p[i][1])

    results = []
    for i in range(q):
        parts = lines[n + 1 + i].split()
        if parts[0] == '1':
            idx, a, b = int(parts[1]), int(parts[2]), int(parts[3])
            p[idx - 1] = (a, b)
            st.update(idx, a / b)
        else:
            l, r = int(parts[1]), int(parts[2])
            if l == r:
                res = l / r
            else:
                prod = 1.0
                for k in range(l - 1, r):
                    prod *= p[k][0] / p[k][1]
                if prod == 0:
                    res = 0.0
                else:
                    res = p[l - 1][0] / p[l - 1][1] * prod
            results.append(f"{res:.10f}")

    return '\n'.join(results)
