    depth = {}
    order = []
    queue = [root]
    depth[root] = 0
    parent[root] = 0

    while queue:
        u = queue.pop(0)
        order.append(u)
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                queue.append(v)

    if root != 1:
        root = 1
        parent = {v: p for p, v in parent.items()}
        depth = {v: d for d, v in depth.items()}
        order = [1] + [i for i in range(1, num_nodes + 1) if i != 1]

    num_level = depth.values()
    max_depth = max(num_level)

    if max_depth != n - 1:
        return "0\n"

    level_counts = defaultdict(int)
    for i in range(1, num_nodes + 1):
        level_counts[depth[i]] += 1

    expected = {0: 1}
    for i in range(1, n):
        expected[i] = 1 << i

    for d in range(n):
        if level_counts[d] != expected[d]:
            return "0\n"

    candidates = []
    for v in range(1, num_nodes):
        if depth[v] < n - 1:
            children_of_v = [child for child in adj[v] if parent.get(child) == v]

            if children_of_v:
                siblings_map = defaultdict(set)
                for child in children_of_v:
                    for v1 in adj[child]:
                        if v1 != v:
                            siblings_map[id(child)].add(v1)

                candidates.append(v)

    valid = []
    for v in range(1, num_nodes):
        if depth[v] < n - 1:
            children_of_v = [child for child in adj[v] if parent.get(child) == v]
            if children_of_v:
                valid_p = 1
            else:
                valid_p = 0
            p = parent.get(v)
            if p > 0 and valid_p:
                valid.append(p)

    valid_sorted = sorted(set(valid))

    if not valid_sorted:
        return "0\n"

    result = str(len(valid_sorted)) + '\n' + ' '.join(map(str, valid_sorted)) + '\n'
    return result
