    def is_convex_quadrilateral(p, q, r, s):
        c1 = cross_product(p, q, r)
        c2 = cross_product(q, r, s)
        c3 = cross_product(r, s, p)
        c4 = cross_product(s, p, q)
        return c1 > 0 and c2 > 0 and c3 > 0 and c4 > 0

