            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    for x in p:
        a_comp = a - x
        if a_comp in num_map:
            union(num_map[x], num_map[a_comp])

    for x in p:
        b_comp = b - x
        if b_comp in num_map:
            union(num_map[x], num_map[b_comp])

